
const NKJ_DEFAULT_LOGO = "data:image/png;base64,";

function getNKJLogo(){
  try{
    return localStorage.getItem("nkjStoreCustomLogo") || NKJ_DEFAULT_LOGO;
  }catch(e){
    return NKJ_DEFAULT_LOGO;
  }
}

function applyNKJLogo(){
  const src = getNKJLogo();
  document.querySelectorAll('img[data-nkj-logo]').forEach(img => {
    img.src = src;
  });
}

document.addEventListener("DOMContentLoaded", applyNKJLogo);
window.addEventListener("storage", e => {
  if(e.key === "nkjStoreCustomLogo") applyNKJLogo();
});
